def experiment(inputs):
    import random
    seeds = inputs.get('seeds', [42])
    scores = []
    for s in seeds:
        random.seed(s)
        scores.append(random.uniform(0.72, 0.92))
    return {'measurements': {'objective_novelty_score': scores}}

